/**
 * Tests for the confirmation a generated playlist's first edit shows: what it
 * says the edit does to the playlist, its two commands, and that each one
 * reports its own answer.
 */
import { cleanup, fireEvent, render } from '@testing-library/svelte';
import { afterEach, describe, expect, it, vi } from 'vitest';

import GeneratedPlaylistDialog from './GeneratedPlaylistDialog.svelte';

afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

/** The sentence the dialog states about a generated playlist it is editing. */
const BODY =
  'This playlist is generated by Last.fm and refreshes daily. Editing it makes it ' +
  'yours: it stops refreshing and no longer expires.';

/**
 * Renders the dialog for one service.
 *
 * @param onconfirm What the Edit Playlist command should run.
 * @param oncancel What the Cancel command should run.
 * @returns The rendered container.
 */
function renderDialog(onconfirm: () => void = () => {}, oncancel: () => void = () => {}) {
  return render(GeneratedPlaylistDialog, {
    props: { service: 'Last.fm', onconfirm, oncancel }
  });
}

describe('the generated playlist dialog', () => {
  it('states what editing it does, and offers the two commands', () => {
    const { getByText } = renderDialog();

    expect(getByText('Edit This Playlist?')).toBeTruthy();
    expect(getByText(BODY)).toBeTruthy();
    expect(getByText('Cancel')).toBeTruthy();
    expect(getByText('Edit Playlist')).toBeTruthy();
  });

  it('cancels without editing', async () => {
    const onconfirm = vi.fn();
    const oncancel = vi.fn();
    const { getByText } = renderDialog(onconfirm, oncancel);

    await fireEvent.click(getByText('Cancel'));

    expect(oncancel).toHaveBeenCalledTimes(1);
    expect(onconfirm).not.toHaveBeenCalled();
  });

  it('confirms the edit', async () => {
    const onconfirm = vi.fn();
    const oncancel = vi.fn();
    const { getByText } = renderDialog(onconfirm, oncancel);

    await fireEvent.click(getByText('Edit Playlist'));

    expect(onconfirm).toHaveBeenCalledTimes(1);
    expect(oncancel).not.toHaveBeenCalled();
  });
});
